import{_ as p,c as e,o as r,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"艮","description":"高岛易断 - 艮","frontmatter":{"title":"艮","description":"高岛易断 - 艮"},"headers":[],"relativePath":"zh/classics/takashima/052.md","filePath":"zh/classics/takashima/052.md"}'),i={name:"zh/classics/takashima/052.md"};function l(n,a,d,t,s,c){return r(),e("div",null,[...a[0]||(a[0]=[h('<h1 id="艮" tabindex="-1">艮 <a class="header-anchor" href="#艮" aria-label="Permalink to “艮”">​</a></h1><h2 id="艮-1" tabindex="-1">艮 <a class="header-anchor" href="#艮-1" aria-label="Permalink to “艮”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>艮：艮其背，不获其身，行其庭，不见其人，无咎。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>《艮》之卦一奇巍然居上，二偶分列在下。一奇居上，象人道，二偶分列，象人身。凡人自首以下，前面眉目手足，皆二偶，惟背脊直下成奇，故眉目手足皆动，惟背不动，不动为《艮》，《艮》止也，故曰“艮其背”。夫人必面相对，乃为相见，“艮其背”，则相背而不相见，背在后，身在前，故曰“不获其身”。《艮》为门庭，心相背，行亦相背，相背则不相遇，不相遇，必不相见，故曰“行其庭，不见其人”。义皆取诸背也。</p><h2 id="象辞" tabindex="-1">象辞 <a class="header-anchor" href="#象辞" aria-label="Permalink to “象辞”">​</a></h2><p>兼山，艮。君子以思不出其位。</p><h2 id="象辞注" tabindex="-1">象辞注 <a class="header-anchor" href="#象辞注" aria-label="Permalink to “象辞注”">​</a></h2><p>卦象一山之外，又有一山，两山相对，其势相连，有兼并之义，谓之兼山。凡八纯卦，皆上下一体，互相联络，惟《艮》则上下两山，各止其所，不相往来，此所以为《艮》止也。君子法《艮》之象，《艮》以山为止之所，人以位为止之所，思之思之，不敢或出焉。此即《中庸》所谓“素其位而行，不愿乎其外”也。</p><h2 id="占断" tabindex="-1">占断 <a class="header-anchor" href="#占断" aria-label="Permalink to “占断”">​</a></h2><p>○　问时运：时运平平，宜退守，不宜妄动。</p><p>○　问战征：宜各守疆界，不得驰域外之想。</p><p>○　问营商：宜确守本业，不得贪意外之财。</p><p>○　问功名：宜守旧，毋干幸进。</p><p>○　问家宅：此宅地位虽狭，不可妄行改造。</p><p>○　问婚姻：命由前定，不可贪富嫌贫。</p><p>○　问讼事：不可以曲作直。</p><p>○　问失物：当在原处寻之，可得。</p><p>○　问疾病：止者终也，带病延年而已。</p><p>○　问六甲：生女。</p><h2 id="初六解" tabindex="-1">初六解 <a class="header-anchor" href="#初六解" aria-label="Permalink to “初六解”">​</a></h2><p>居《艮》之初，当趾之位。凡人动止，必自趾始，是以欲止其心，先止其身，欲止其身，先止其趾。趾止则不妄动，不妄动，则止得其所，而无失矣，故曰“无咎”。吉凶悔吝，每生乎动，止其趾，止动之初也，是遏人欲于将萌，存天理于未著，图之于始，尤当持之以永，故曰“利永贞”。《象传》曰“未失正也”，谓以阴居阳，位虽失正，而止其所止，初基正矣，故曰未失其正。</p><h2 id="初六占" tabindex="-1">初六占 <a class="header-anchor" href="#初六占" aria-label="Permalink to “初六占”">​</a></h2><p>○　问时运：运途初交，宜守稳步，不可妄进，自得无咎。</p><p>○　问战征：屯军山足，宜静守，不宜妄动。</p><p>○　问营商：宜知足。</p><p>○　问功名：初步虽微，不失其正。</p><p>○　问家宅：此宅近在山麓，可以长住，无咎。</p><p>○　问婚姻：百年好合，无咎。</p><p>○　问疾病：病是足疾，艰于步履，一时难愈。</p><p>○　问讼事：不失其正，无咎。</p><p>○　问行人：因足不能行，一时不归。</p><p>○　问失物：必不遗失，宜就地下僻处寻之。</p><p>○　问六甲：生女，防有足疾。</p><h2 id="初六案例" tabindex="-1">初六案例 <a class="header-anchor" href="#初六案例" aria-label="Permalink to “初六案例”">​</a></h2><p>明治二十四年，占某大臣气运，筮得《艮》之《贲》。</p><p>断曰：《艮》者两山并峙之卦，两山并峙，则不能前进，有止而不动之象也。今贵下占气运，得此初爻，“趾”足指也，凡人行动，以足在前，“艮其趾”，则足趾不动，而全体亦因之不动，即《大象》所谓“君子以思不出其位”也。知贵下宜永守其正，葆此爵位，无容再求升用，否则妄动，未免有咎矣。</p><h2 id="六二解" tabindex="-1">六二解 <a class="header-anchor" href="#六二解" aria-label="Permalink to “六二解”">​</a></h2><p>“腓”，《本义》释为足肚，《正字通》云，胫后肉腓也。腓上于趾，故二象之。《咸》之二曰“咸其腓”，《咸》主夫感；《艮》二曰“艮其腓”，《艮》主夫止，止则安止不动矣。然趾与腓，皆为动体，本不欲止也，所欲止者心也。心欲止，则趾不能不止；趾既止，而腓亦随之，是腓固随趾为动止者也。“拯”，援也，“不拯其随”者，谓三“限”在上，不肯俯听，趾腓相随而动，故二之心有“不快”也。《象传》曰，“未退听也”，谓既不能拯其动，又不能退而听命，以从其止，是以“其心不快”矣。</p><h2 id="六二占" tabindex="-1">六二占 <a class="header-anchor" href="#六二占" aria-label="Permalink to “六二占”">​</a></h2><p>○　问时运：运途有阻，宜裹足不前，不宜随心而动。</p><p>○　问战征：止，不进也，坚守不动，又无外援，是以戚戚也。</p><p>○　问营商：货物止而不售，甚为可忧。</p><p>○　问功名：不得寸进，又苦无大力之援。</p><p>○　问疾病：“腓”，病也，《诗》云“百卉具腓”，为秋风所虐也。此病亦必是秋症，恐非药力所能救援也。甚为可忧。</p><p>○　问婚姻：腓亦为避，宜避绝之。</p><p>○　问六甲：生女。</p><h2 id="六二案例" tabindex="-1">六二案例 <a class="header-anchor" href="#六二案例" aria-label="Permalink to “六二案例”">​</a></h2><p>应友人石坂氏之请，为占矿山事，筮得《艮》之《蛊》。</p><p>断曰：《艮》为山，腓在山足之上，《彖》曰“艮其背”，背身后也，爻之取象，皆在背后。为占矿山，而得此爻，知矿山之穴，宜在山背。初为趾，二为腓，腓上于趾，知其穴又在股之下，足之上也。“艮，止也”，论其事，谓停止。在趾与腓本喜动，不喜止，曰止，其心必为之不快矣。今必倡始，议将停止，随从者亦无力拯救，固宜作退步为是。必待五爻“悔亡”，得其辅助，可复与也。以爻计之，当在三年之后。</p><p>明治二十七年冬至，占战后形势，筮得《艮》之《蛊》，呈之内阁总理大臣。</p><p>断曰，卦体取诸山，卦象取诸身，身本动也，山则止而不动；卦又于身之中取诸背，背无所见，背亦不动也。卦与《震》反，《震》动而《艮》止，所谓动极而止者也。今占战后形势，得《艮》二爻，初为趾，二为腓，腓进于趾，腓能屈能伸，其动尤甚，其力较强，论战后形势，固较昔而尤强也。战后得此巨数偿金，在从征军士，皆自夸威武之力，每每藐视文官。至在朝大臣，总计全局，当以此金拓张军备，是为首要，而不能随从军士之心，其心未免不快也。且《序卦》曰，“艮者，止也”，谓大战之后，宜休养，不宜躁动，古称止戈曰武，此其征也。武士之心，固好动，不好静，止而不动，致多郁郁不乐，亦情所必有。观腓之动，凡腓自动，心为之也；在武士之动，亦非武士所能自主，朝廷为之也：是在朝廷静镇之耳。</p><h2 id="九三解" tabindex="-1">九三解 <a class="header-anchor" href="#九三解" aria-label="Permalink to “九三解”">​</a></h2><p>“限”者，门限，为内外之界限。三处内外之间，横亘一画，故象限。“列”，分解也，虞氏作裂。“夤”，通作；马云“夹脊肉”。按《咸》五曰“脢”，《易传》谓“在脊曰脢”，郑云，“脢，脊肉”，是夤与脢，字异而义同也。“薰”，通作熏，灼也。三之《艮》限，为隔绝一身上下，使不相通，则将分心背而为二，一若门限之隔绝内外，此释氏所谓“降伏其心”是也。以强伏其心，心者，火也，心火上灼，烛烛炎炎，薰灼于方寸之中，不可扑灭，则其心危矣，《诗》云“忧心如薰”，此之谓也。岂知心本虚灵，感而遂通，《咸》之“咸其脢”，与《艮》之“艮其限”，一感一止，初无二致，《彖传》所谓“时止则止，时行则行，动静不失其时”，一任心之自然，而未可以隔绝为止者。隔绝为止，是欲定其心，乃适以危其心，心岂可以强制者哉！夫人一身脉络血气，上下前后，必周流贯通，无所阻隔，而此心自觉泰然，否则上不降，下不升，则脉络不通，血肉分裂，心其能得安乎？故曰“厉”。“薰心”，《象传》易“厉”曰“危”，盖危较厉，为更可惧也。</p><h2 id="九三占" tabindex="-1">九三占 <a class="header-anchor" href="#九三占" aria-label="Permalink to “九三占”">​</a></h2><p>○　问时运：运途顺逆，皆当顺时，强制者危。</p><p>○　问战征：两军相对，各争疆界，安得划界自守乎？自守者危矣。</p><p>○　问营商：货物务在流通，乃可获利，况今万国通商，输入输出，互相交易，若闭关自限，必穷之道也，可危甚矣。</p><p>○　问功名：专守一艺者，必非大器。</p><p>○　问家宅：治家之道，内外出入，固宜严谨，但不宜隔绝，隔绝则财用不通，而家道危矣。</p><p>○　问婚姻：婚姻之道，本由天合，若苟守门户，不能成两姓之欢。</p><p>○　问疾病：必是隔症，上下不交，血脉不通，病势可危。</p><p>○　问讼事：是上下之情不达，曲直难分。</p><p>○　问六甲：生女，防难产。</p><h2 id="九三案例" tabindex="-1">九三案例 <a class="header-anchor" href="#九三案例" aria-label="Permalink to “九三案例”">​</a></h2><p>某氏来请占某贵显气运，筮得《艮》之《剥》。</p><p>断曰：爻象为血脉不通，心背分裂，势颇可危。今贵下占气运，而得此爻，知贵下于政府内外，情好或多不协。其所由来，在于位置自高，不屑与人往来，遂至势分隔绝，情意不通，其势几成孤立，虽有才智，无所展布，此身危矣。爻辞所云“艮其限，裂其夤，厉，薰心”，其象如是，贵下宜旁求诸《咸》。《咸》五曰“咸其脢”，斯无悔矣。</p><h2 id="六四解" tabindex="-1">六四解 <a class="header-anchor" href="#六四解" aria-label="Permalink to “六四解”">​</a></h2><p>“身”者，总括全体而言，分言之，则一身亦有上下之别。六四居下卦之上，上卦之下，当心之位，在一身之中也。爻得柔正，上比六五，为能“止其所止”，洁身自好，虽不能兼善天下，亦可以独善其身，较之内卦三爻，为稍胜也。但以阴居阴，不堪有为，只能以身为天下模范而已，故曰“艮其身，无咎”。三爻言心，四爻言身，心虚而身实，期人含虚而践实，斯不坠入释氏虚无之弊。《象传》以“止诸躬”释之，躬，犹身也。是以身止心，即《大象》所谓“思不出其位”也。</p><h2 id="六四占" tabindex="-1">六四占 <a class="header-anchor" href="#六四占" aria-label="Permalink to “六四占”">​</a></h2><p>○　问时运：运途柔顺，能保其身，自得无咎。</p><p>○　问战征：难望进取，但于我身无所伤败，咎复何有？</p><p>○　问营商：只能保本。</p><p>○　问功名：无得无失。</p><p>○　问家宅：安居无咎。</p><p>○　问婚姻：平平。</p><p>○　问疾病：是带病延年之症。</p><p>○　问失物：即在身上寻之。</p><p>○　问六甲：生女。</p><h2 id="六四案例" tabindex="-1">六四案例 <a class="header-anchor" href="#六四案例" aria-label="Permalink to “六四案例”">​</a></h2><p>明治二十年，占某贵显气运，筮得《艮》之《旅》。</p><p>断曰：四爻介上下之交，当心之位，心内而身外，曰“艮其身”，是兼身心而言也。然《艮》主夫止，止则无所作为，是不足以见功，但求无咎而已。今贵下占气运，得《艮》四爻，爻曰“艮其身”，有保身安命之象。四爻比近尊位，知贵下爵位已显，为宜谨守职分，夙夜弗懈，以保全一身声名禄位，安享此太平之福，复有何咎？《大象》所谓“君子以思不出其位”，惟贵下有焉。</p><h2 id="六五解" tabindex="-1">六五解 <a class="header-anchor" href="#六五解" aria-label="Permalink to “六五解”">​</a></h2><p>五居外卦之中，二偶分列，有辅之象。按《咸》上曰，“辅，腾口悦也”，是辅所以出言；“艮其辅”，斯言无失言矣。君子之道，寡言则寡悔。“艮其辅”者，固非止其辅而不言也，惟在时然后言耳。时然后言，则言有其序，可以默则默，可以语则语，语默不失其时，故“悔亡”。《象传》以“中正”释之，“艮其辅”，谓上得其中正，是以“言有序”而“无悔”也。</p><h2 id="六五占" tabindex="-1">六五占 <a class="header-anchor" href="#六五占" aria-label="Permalink to “六五占”">​</a></h2><p>○　问时运：运得中正，故无悔忧。</p><p>○　问战征：行军之际，最忌谣言妄作，惑乱军心，“艮其辅”使不妄言，斯号令严明，所向无敌矣。</p><p>○　问营商：商情犹如军情，消息不容漏泄，“艮其辅”，则言得其要矣。</p><p>○　问功名：巧言必黜，昌言则拜，言得中正，立谈可取卿相也。</p><p>○　问家宅：此宅位得中正，居之无悔。</p><p>○　问婚姻：媒妁之言，每多虚诞，听者宜慎。</p><p>○　问疾病：必是牙关紧闭，口不出声，得能发声，病乃可治。</p><p>○　问六甲：生女。</p><h2 id="六五案例" tabindex="-1">六五案例 <a class="header-anchor" href="#六五案例" aria-label="Permalink to “六五案例”">​</a></h2><p>明治二十四年十一月，贵族院议员日野西公、善神道总裁稻叶正邦来访，曰：今春恶疫流行，三条相国以下二三元老，遽而薨逝，实国家之不幸也。寻又有大津之暴举，浓尾之震灾，以及伊势神宫庭燎无风启灭。此皆意外凶变，自古罕闻，而适于今年叠见之。所谓国家将兴，必有祯祥，国家将亡，必有妖孽，此其兆也，能不惧乎？今议会开设在近，是为上下臣民，最所注意，请君一卜，以见议院之兴败。余曰：仆昨年十二月既占之矣，以爻辞上呈松方总理、土方宫内二公，卦爻遇《艮》之《渐》。</p><p>断曰：《大象》曰“兼山”，为两山兼峙，阻绝往来，有上下不通之象。今占众议院，得《艮》五爻，爻辞曰“艮其辅”，是止众议之辅，使不得以无稽之言妄干上听；曰“言有序，”谓议者所言，当必秩秩有序，斯可听纳。爻象若预知此番众议，必多出言不逊，好与政府为难，卒至奉敕解散，亦势所必有也。即使众议言皆有序，亦但曰“无悔”而已，未足以见功也。众议院之兆如此。两公听之大感，至十二月，众议院果奉诏敕解散。</p><h2 id="上九解" tabindex="-1">上九解 <a class="header-anchor" href="#上九解" aria-label="Permalink to “上九解”">​</a></h2><p>上居《艮》之终，即止之终也。“敦”，加厚也，所谓泰山不让土壤，故能成其高，即敦厚之谓也。上能以敦厚自止，是以获吉。《艮》六爻，惟上言吉，盖《艮》之为道，上爻足以尽之。上能坚守此心，知其所止，是以厚重如山，不可动摇，吉莫大焉。《象传》以“厚终”释之，谓止以敦而乃安，敦以终而弥厚，是《艮》之所“成终”者，在此厚，而所以“成始”者，亦即在此厚也。</p><h2 id="上九占" tabindex="-1">上九占 <a class="header-anchor" href="#上九占" aria-label="Permalink to “上九占”">​</a></h2><p>○　问时运：运途至此，无可复进，惟厚益加厚，是以得吉。</p><p>○　问战征：地位至上已极，要在兵力加厚，无不获吉。</p><p>○　问营商：是上手生意，价高物美，获利必厚。</p><p>○　问功名：必应上选，吉。</p><p>○　问家宅：必是世代忠厚之家，吉。</p><p>○　问婚姻：吉。</p><p>○　问疾病：素体厚实，不药有喜。</p><p>○　问六甲：生女。</p><h2 id="上九案例" tabindex="-1">上九案例 <a class="header-anchor" href="#上九案例" aria-label="Permalink to “上九案例”">​</a></h2><p>明治二十七年三月，某贵显来，请占气运，筮得《艮》之《谦》。</p><p>断曰：上处重《艮》之极，即为兼山之上，山以厚重为体，山愈高则愈厚，故全卦之义，归成于上，而上乃独得其吉，即可见晚运之亨通也。今贵下占气运，而得上爻，知贵下身居民上，爵位崇高，人民瞻望，俨同山斗，而素怀忠厚，未尝以势位凌人。“敦”者，厚也，《艮》者，止也，贵下当止其所止，厚益加厚，于己于人，无不获吉。大运之盛，于此可见。</p>',111)])])}const m=p(i,[["render",l]]);export{b as __pageData,m as default};
